hl.config({
    decoration = {
        rounding = 8,
        -- Glass, not haze. The old size 3 / passes 1 was a cheap kernel meant
        -- to sit behind opaque app windows; a bar you look *through* needs a
        -- wider blur, more passes, vibrancy to keep the teal wallpaper alive
        -- behind it, and a little noise so the surface has grain instead of
        -- reading as flat vector.
        -- LIQUID vs TINTED PLASTIC. The difference is almost entirely
        -- vibrancy: it is the saturation the blur keeps in what it smears.
        -- At 0.35 the wallpaper behind the island survived as grey-teal
        -- mush, which is exactly what a sheet of tinted acrylic looks like.
        -- At 0.55 the colour behind the bar stays colour -- the pill reads
        -- as a lens with something moving under it. size 8 widens the
        -- kernel enough that individual wallpaper features stop being
        -- legible through it and become fields, which is the other half.
        blur = {
            enabled = true,
            size = 8,
            passes = 3,
            noise = 0.015,
            contrast = 1.0,
            brightness = 0.90,
            vibrancy = 0.55,
            vibrancy_darkness = 0.25,
            popups = true, -- eww panels get the same treatment
            popups_ignorealpha = 0.2,
        },
        shadow = {
            enabled = true,
            range = 4,
            render_power = 4,
            color = "rgba(1a1a1aee)",
        },
    },
})

